const ctx = $json;
const patient = ctx.patient || {};
const doctors = ctx.doctors || [];
const messages = ctx.messages || [];
const relatedSlot = ctx.related_slot || null;
const offeredSlots = ctx.offered_slots || [];
const zone = 'Europe/Lisbon';
const today = DateTime.now().setZone(zone).toFormat("yyyy-MM-dd (cccc)");
const _pt = ['segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado','domingo'];
const _now = DateTime.now().setZone(zone);
const _next14 = [];
for (let _i = 0; _i < 14; _i++) { const _d = _now.plus({ days: _i }); const _lab = _i === 0 ? ' (hoje)' : (_i === 1 ? ' (amanhã)' : ''); _next14.push(_d.toFormat('dd/MM/yyyy') + ' = ' + _pt[_d.weekday - 1] + _lab); }
const _prox = [];
for (let _w = 1; _w <= 7; _w++) { let _d = _now.plus({ days: 1 }); while (_d.weekday !== _w) _d = _d.plus({ days: 1 }); _prox.push('próxima ' + _pt[_w - 1] + ' = ' + _d.toFormat('dd/MM/yyyy')); }
const isPlaceholder = /^Novo contacto /.test(patient.name || '');
const fmt = (iso) => { try { return DateTime.fromISO(iso, { setZone: true }).setZone(zone).toFormat("dd/MM/yyyy 'às' HH:mm"); } catch (e) { return iso; } };

const lines = [];
lines.push('Data de hoje em Lisboa: ' + today + '.');
lines.push('TABELA DE DATAS (Lisboa) — use SEMPRE estes valores para qualquer data relativa; NUNCA calcule datas nem dias da semana de cabeça:');
lines.push('  Próximos dias: ' + _next14.join('; ') + '.');
lines.push('  Referências: ' + _prox.join('; ') + '.');
lines.push('Clínica: ' + (ctx.clinic_name || 'a clínica') + '.');
lines.push('Paciente: ' + (isPlaceholder ? '(nome ainda desconhecido — placeholder interno, NUNCA o use ao falar com o paciente; se ele disser o nome, registe-o com patient_set_name)' : (patient.name || '(sem nome ainda)')) + '.');
lines.push(patient.primary_doctor_name ? ('Médico habitual do paciente: ' + patient.primary_doctor_name + (patient.primary_doctor_id ? (' (id: ' + patient.primary_doctor_id + ')') : '') + '.') : 'O paciente ainda não tem médico habitual atribuído.');
lines.push('Tipo de conversa: ' + (ctx.conversation_type || 'general') + '.');
if (relatedSlot && relatedSlot.doctor_name) {
  lines.push('Vaga relacionada com esta conversa (facto — hora de Lisboa, não converta): ' + fmt(relatedSlot.start_time) + ' com ' + relatedSlot.doctor_name + '.');
}
if (offeredSlots && offeredSlots.length) {
  lines.push('Vagas JÁ oferecidas nesta conversa (o paciente pode estar a escolher uma destas; horas de Lisboa):');
  for (const s of offeredSlots) {
    lines.push('  • slot_id ' + s.slot_id + ' — ' + fmt(s.start_time) + (s.doctor_name ? (' com ' + s.doctor_name) : ''));
  }
}
if (ctx.cancel_pending) {
  lines.push('Nota: já foi sugerido ao paciente remarcar em vez de cancelar. Se ele insistir agora em cancelar, use cancel_booking (que desta vez cancela mesmo).');
}
if (doctors && doctors.length) {
  lines.push('Médicos da clínica (nome — id, use o id exato em p_doctor_id): ' + doctors.map(d => d.name + ' — ' + d.id).join('; ') + '.');
}
lines.push('');
lines.push('Histórico da conversa (mais antigo primeiro):');
let lastPatient = '';
for (const m of messages) {
  const who = m.sender_type === 'patient' ? 'Paciente' : (m.sender_type === 'agent' ? 'Agente' : 'Staff');
  lines.push(who + ': ' + m.body);
  if (m.sender_type === 'patient') lastPatient = m.body;
}
lines.push('');
if (lastPatient) {
  lines.push('MENSAGEM MAIS RECENTE DO PACIENTE (é a esta que deve responder): "' + lastPatient + '"');
}
lines.push('Primeiro perceba o que o paciente quer; se não for claro, faça UMA pergunta curta em vez de adivinhar ou agir. Use ferramentas só quando precisar de dados reais ou de agir sobre a marcação.');

if (isPlaceholder) {
  lines.push('IMPORTANTE: o nome deste paciente ainda é desconhecido. Se concretizar uma marcação nesta conversa, peça o nome na própria mensagem de confirmação (ex.: "…pode dizer-me o seu nome?") para o poder registar com patient_set_name.');
}


// --- Agent presentation settings (from /settings -> Agente, via agent_context) ---
const A = ctx.agent_settings || {};
const _pres = [];
_pres.push(A.name ? ('Apresenta-te como "' + A.name + '" quando fizer sentido (ex.: no cumprimento).') : 'Nao uses um nome proprio para te apresentares.');
_pres.push(A.tone === 'informal' ? 'Trata o paciente por tu (informal), de forma calorosa e natural.' : 'Trata o paciente por voce (formal).');
_pres.push(A.language === 'mirror' ? 'Responde SEMPRE no mesmo idioma da ultima mensagem do paciente (portugues ou ingles).' : 'Responde sempre em portugues europeu.');
_pres.push(A.use_emoji ? 'Podes usar emojis com moderacao.' : 'Nao uses emojis.');
if (A.signature) _pres.push('Termina a mensagem com a assinatura: "' + A.signature + '".');
if (A.custom_instructions) _pres.push('Instrucoes adicionais da clinica: ' + A.custom_instructions);
lines.push('');
lines.push('APRESENTACAO E ESTILO (aplica-se a forma como escreves; NUNCA altera as regras de marcacao, cancelamento nem o aviso STOP/RGPD):');
for (const _p of _pres) lines.push('  - ' + _p);

return { json: { conversation_id: ctx.conversation_id, text: lines.join('\n') } };

const body = ($('agent_inbound_batch').item.json.joined_body || '').trim();
const conv = $('agent_inbound_batch').item.json.conversation_id;
const tokens = body.toUpperCase().split(/[^A-ZÁÀÂÃÉÊÍÓÔÕÚÜÇ]+/).filter(Boolean);
const STOP  = ['STOP','PARAR','PARE','SAIR','REMOVER','CHEGA'];
const START = ['START','ATIVAR','SUBSCREVER','RETOMAR','INICIAR'];
let action = 'continue';
if (tokens.some(t => STOP.includes(t))) action = 'opt_out';
else if (tokens.some(t => START.includes(t))) action = 'opt_in';
return { json: { action, conversation_id: conv } };

const a = $json.action;
const conv = $json.conversation_id;
if (a === 'opt_out') return { json: { conversation_id: conv, rpc: 'patient_opt_out', message: 'Registámos o seu pedido. Não voltará a receber mensagens automáticas desta clínica. Responda START para reativar.' } };
return { json: { conversation_id: conv, rpc: 'patient_opt_in', message: 'Subscrição reativada. Voltará a receber as nossas mensagens. Obrigado.' } };

const ctx = $json;
let raw = '';
try { raw = ($('agent_inbound_batch').item.json.joined_body) || ''; } catch(e){ raw=''; }
if (!raw) {
  const msgs = (ctx.messages || []).filter(m => (m.sender_type||m.direction) === 'patient');
  raw = (msgs.length ? (msgs[msgs.length-1].body || '') : '');
}
raw = (raw || '').toString();
const norm = raw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const hasQ = /\?/.test(raw);
const uncertain = /\b(nao sei|talvez|depende|nao tenho a certeza|logo vejo|se possivel|como assim|mas)\b/.test(norm);
// A cancel/reschedule/booking request is NOT an accept or decline of THIS offer.
// Defer any such intent to the LLM (which has the cancel/reschedule tools).
const intent = /\b(cancelar|desmarcar|remarcar|remarcacao|marcar|outro dia|outra data|outro horario|noutro dia|mudar|trocar de dia|trocar de medico|trocar de hora)\b/.test(norm);
const acc = /\b(sim|aceito|aceite|aceitar|confirmo|confirmado|confirmar|combinado|perfeito|otimo|ok|okay|claro|pode ser|por mim|tudo bem|esta bem|ta bem|fica bem|pode marcar|mais cedo)\b/.test(norm);
const dec = /\b(nao|nem|negativo|mantenho|prefiro nao|nao quero|nao posso|nao da|nao consigo|deixa estar|melhor nao|fico com)\b/.test(norm);
let decision = 'unclear';
if (!hasQ && !uncertain && !intent) {
  if (acc && !dec) decision = 'accept';
  else if (dec && !acc) decision = 'decline';
}
return { json: { ...ctx, decision, _reply_raw: raw } };

const res = $json;
const ctx = $('Classify reply').item.json;
const zone = 'Europe/Lisbon';
const fmt = (iso) => { try { return DateTime.fromISO(iso, { setZone: true }).setZone(zone).toFormat("dd/MM 'às' HH:mm"); } catch(e){ return iso; } };
const nm = (ctx.patient && ctx.patient.name && !/^Novo contacto /.test(ctx.patient.name)) ? ctx.patient.name : '';
const greet = nm ? (nm + ', ') : '';
const rs = ctx.related_slot || {};
const when = rs.start_time ? fmt(rs.start_time) : '';
const doc = rs.doctor_name ? (' com ' + rs.doctor_name) : '';
const st = res && res.status;
let ack;
if (ctx.conversation_type === 'slot_cascade' && st === 'accepted') {
  ack = greet + 'está confirmado: a sua consulta passou para ' + when + doc + '. Até já.';
} else if (ctx.conversation_type === 'confirmation' && st === 'confirmed') {
  ack = greet + 'obrigado pela confirmação. Fica mantida a sua consulta de ' + when + doc + '.';
} else if (st === 'stale') {
  ack = greet + 'essa vaga já não está disponível. A recepção entra em contacto para encontrar outra.';
} else {
  ack = greet + 'não consegui concluir agora; a recepção vai verificar e entra em contacto.';
}
return { json: { conversation_id: ctx.conversation_id, ack } };

const res = $json;
const ctx = $('Classify reply').item.json;
const zone = 'Europe/Lisbon';
const fmt = (iso) => { try { return DateTime.fromISO(iso, { setZone: true }).setZone(zone).toFormat("dd/MM 'às' HH:mm"); } catch(e){ return iso; } };
const nm = (ctx.patient && ctx.patient.name && !/^Novo contacto /.test(ctx.patient.name)) ? ctx.patient.name : '';
const greet = nm ? (nm + ', ') : '';
const rs = ctx.related_slot || {};
const when = rs.start_time ? fmt(rs.start_time) : '';
let ack;
if (ctx.conversation_type === 'slot_cascade') {
  ack = greet + 'sem problema, mantém a sua marcação atual. Obrigado pela resposta.';
} else {
  ack = greet + 'a sua marcação' + (when ? (' de ' + when) : '') + ' foi desmarcada. Se quiser remarcar, é só dizer.';
}
return { json: { conversation_id: ctx.conversation_id, ack, conversation_type: ctx.conversation_type, slot_id: (res && res.slot_id) || null } };
